-- Daily challenges for 2026-11-15: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-11-15. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('keeping-promises-to-yourself', 'Keeping Promises to Yourself', 'For anyone who keeps their word to others but lets their own plans slide. Each day is one small promise to yourself, made kindly and kept, so you can trust your own word a little more.', 'Habits', 365, array['Habits', 'Self-Esteem', 'Goals']::text[], 1, '2026-11-15T17:00:00+00:00'::timestamptz),
  ('enjoying-art-and-beauty', 'Enjoying Art and Beauty', 'For anyone who wants more beauty in an ordinary day. Each day is one small way to look at, listen to or make room for art, design and lovely things, from a painting online to light on a wall.', 'Creativity', 365, array['Mindfulness', 'Self-Care']::text[], 1, '2026-11-15T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('keeping-promises-to-yourself', 'enjoying-art-and-beauty');

